    "页面在新标签页中打开的链接（如商品详情）会显示为独立窗口": "ページが新しいタブで開くリンク（商品の詳細など）は、独立したウィンドウに表示されます",
    "卖家发送网盘分享后，复制完整的分享文本（含链接和提取码），再点击「收录网盘链接」": "出品者からネットディスクの共有が届いたら、共有テキスト全体（リンクと抽出コード）をコピーしてから、「ネットディスクリンクを取り込む」をクリックしてください",
    "卖家发来网盘分享后，复制完整的分享文本（含链接和提取码），回到此页签点击「收录网盘链接」": "出品者からネットディスクの共有が届いたら、共有テキスト全体（リンクと抽出コード）をコピーしてこのタブに戻り、「ネットディスクリンクを取り込む」をクリックしてください",
    "已在默认浏览器中打开": "既定のブラウザーで開きました",
    "闲鱼页面的打开方式": "Xianyu ページの開き方",
    "自 1.7.7 起，闲鱼页面不再使用软件的内置浏览器（Booth、网盘等页面仍在其中打开），改为以下两种方式之一": "1.7.7 から、Xianyu のページはアプリの内蔵ブラウザーを使わなくなりました（Booth やネットディスクなどのページは引き続き内蔵ブラウザーで開きます）。次のどちらかの方法で開きます",
    "在软件内打开": "アプリ内で開く",
    "使用独立的内嵌浏览器": "独立した埋め込みブラウザーを使用します",
    "软件不向页面注入或执行脚本，不读写 Cookie，不使用代理设置，也不保存登录状态，通常每次启动软件后需重新扫码登录": "アプリはページへのスクリプトの挿入や実行、Cookie の読み書き、プロキシ設定の使用、ログイン状態の保存を行いません。通常はアプリを起動するたびに QR コードで再ログインが必要です",
    "闲鱼页面交给系统的默认浏览器，与平时使用浏览器相同": "Xianyu のページを既定のブラウザーに任せます。普段ブラウザーを使うのと同じです",
    "两种方式下，复制卖家发来的网盘分享文本后，均可在「闲鱼」页签一键收录": "どちらの方法でも、出品者から届いたネットディスクの共有テキストをコピーすれば、「Xianyu」タブからワンクリックで取り込めます",
    "此前的版本中，有用户在内置浏览器登录闲鱼后账号被平台限制": "以前のバージョンで、内蔵ブラウザーから Xianyu にログインしたユーザーのアカウントがプラットフォームに制限された事例があります",
    "新的内嵌浏览器已去除可能导致该问题的因素，但仍可能被网站识别为应用内浏览器，软件无法保证不触发平台的风控": "新しい埋め込みブラウザーでは原因になり得る要素を取り除きましたが、サイト側からアプリ内ブラウザーと判別される可能性は残ります。プラットフォームのリスク管理に検知されないことは保証できません",
    "账号较为重要时，建议选择默认浏览器": "大切なアカウントの場合は、既定のブラウザーを選ぶことをおすすめします",
    "之后可随时在「闲鱼」页签左侧的「打开方式」中更改": "あとから「Xianyu」タブ左側の「開き方」でいつでも変更できます",
    "设置未能保存": "設定を保存できませんでした",
    "复制链接后将提示打开或收录": "リンクをコピーすると、開くか取り込むかを確認します",
    "已关闭复制提示": "コピー時の確認をオフにしました",
    "登录、聊天和下单均可在此完成": "ログイン・チャット・注文はすべてここで行えます",
    "闲鱼页面在默认浏览器中打开": "Xianyu のページは既定のブラウザーで開きます",
    "闲鱼页面使用独立的内嵌浏览器，软件不保存其登录状态，通常每次启动软件后需重新扫码登录": "Xianyu のページは独立した埋め込みブラウザーで表示します。アプリはログイン状態を保存しないため、通常はアプリを起動するたびに QR コードで再ログインが必要です",
    "卖家发送网盘分享后，复制完整的分享文本（含链接和提取码），页面上方将提示收录；也可在复制后点击「收录网盘链接」": "出品者からネットディスクの共有が届いたら、共有テキスト全体（リンクと抽出コード）をコピーしてください。ページ上部に取り込みの確認が表示されます。コピーしたあとで「ネットディスクリンクを取り込む」をクリックしても取り込めます",
    "复制链接后提示打开或收录": "リンクをコピーしたら、開くか取り込むかを確認する",
    "软件位于前台时查看剪贴板，只识别闲鱼、Booth 和网盘分享链接，不保存其他内容": "クリップボードを確認するのは、アプリが前面にある間だけです。Xianyu・Booth・ネットディスク共有のリンクだけを認識し、ほかの内容は保存しません",
