    "工程列表来自设置中的「Unity 工程文件夹」；工程内的插件请使用 VCC 或 ALCOM 管理": "プロジェクト一覧は設定の「Unity プロジェクトフォルダー」から取得しています。プロジェクト内のパッケージは VCC または ALCOM で管理してください",
    "点击卡片上的「流水线」，可将已导入的衣服、头发、配饰和道具装配到模型，按设定的层级生成菜单开关和图标，并可继续通过 AI 执行其他改模操作": "カードの「パイプライン」では、インポート済みの衣装・髪型・アクセサリー・小物をアバターにセットアップし、指定した階層でメニューのトグルとアイコンを生成します。続けて AI に他の改変を任せることもできます",
