    "点击卡片上的「开启封面」，将在该工程的 Packages 中安装封面插件，每次打开工程或保存场景时自动截取模型正面图作为封面": "カードの「サムネイルを有効化」をクリックすると、プロジェクトの Packages にサムネイル用プラグインをインストールします。プロジェクトを開いたときやシーンを保存したときに、アバターの正面画像を自動で撮影してサムネイルにします",
    "插件仅在 Unity 编辑器中运行，不修改场景，也不会随模型上传": "プラグインは Unity エディター上でのみ動作し、シーンを変更せず、アバターと一緒にアップロードされることもありません",
