    "登录后点击页面右上角的「My Purchases」进入已购列表": "ログイン後、ページ右上の「My Purchases」から購入済み一覧を開きます",
    "在此页面下载的文件将保存到软件的下载文件夹，并自动解压、收录到素材库": "このページでダウンロードしたファイルは、アプリのダウンロードフォルダーに保存され、自動で展開してライブラリに取り込まれます",
    "只收录 Jinxxy 页面发起的下载，在搜索结果等其他网站的页面上发起的下载会被取消": "取り込むのは Jinxxy のページで開始したダウンロードだけです。検索結果など、ほかのサイトのページで開始したダウンロードはキャンセルされます",
    "如下载后未出现在「下载记录」中，文件已由浏览器保存到系统的「下载」文件夹": "ダウンロード後に「ダウンロード履歴」に表示されない場合は、ブラウザーがシステムの「ダウンロード」フォルダーに保存しています",
