    "该工程的 Unity 插件为旧版，不支持生成封面：请在流水线页点击「更新」，待 Unity 编译完成后重试": "このプロジェクトの Unity プラグインは旧バージョンのため、サムネイル生成に対応していません。パイプラインタブで「更新」をクリックし、Unity のコンパイル完了後にお試しください",
