    "方案中有菜单项缺少名称": "プリセットに名前のないメニュー項目があります",
    "文件中含有无法识别的内容，可能不是装配方案，或由更新版本的软件导出": "ファイルに判別できない内容が含まれています。プリセットではないか、新しいバージョンのアプリで書き出された可能性があります",
    "无法读取该文件：不是有效的装配方案（JSON 格式有误）": "このファイルを読み込めません：有効なプリセットではありません（JSON 形式が正しくありません）",
