    "当前工程还没有可保存的结果，请先运行一次流水线": "このプロジェクトにはまだ保存できる結果がありません。先にパイプラインを実行してください",
    "无法保存为方案": "プリセットとして保存できません",
    "当前场景中没有模型，方案的素体 prefab 也不在该工程中": "現在のシーンにアバターがなく、プリセットの素体 prefab もこのプロジェクトにありません",
    "请先在 Unity 中打开包含模型的场景": "先に Unity でアバターのあるシーンを開いてください",
    "当前场景中没有模型，方案的素体 prefab 也不在该工程中：请先在 Unity 中打开包含模型的场景": "現在のシーンにアバターがなく、プリセットの素体 prefab もこのプロジェクトにありません。先に Unity でアバターのあるシーンを開いてください",
    "Unity 尚未连接：请先在「工程」步骤中打开 Unity": "Unity がまだ接続されていません。先に「プロジェクト」ステップで Unity を開いてください",
    "下方仅按工程中的文件判断素材是否已导入": "以下は、プロジェクト内のファイルだけでアセットがインポート済みかどうかを判定しています",
    "流水线正在该工程中运行，请等待其完成": "このプロジェクトでパイプラインが実行中です。完了をお待ちください",
    "方案中的素材均未导入该工程，暂无可装配的内容": "プリセットのアセットがこのプロジェクトに 1 つもインポートされていないため、セットアップできるものがありません",
    "未生成菜单": "メニューは生成していません",
    "菜单效果需在 Play 模式中用 Gesture Manager 逐项测试；确认无误后按 Ctrl+S 保存场景，如需回退，每点击一次「撤销上一步」撤销一步": "メニューの効果は Play モードで Gesture Manager を使って 1 つずつ確認してください。問題がなければ Ctrl+S でシーンを保存します。戻したい場合は、「直前の操作を取り消す」を 1 回クリックするごとに 1 ステップ取り消されます",
    // --- Unity: the plugin, projects, imports, new projects ---
    "该工程尚未安装 Unity 插件，请先在「流水线」页点击「安装并打开 Unity」": "このプロジェクトには Unity プラグインがまだインストールされていません。先に「パイプライン」タブで「インストールして Unity を開く」をクリックしてください",
    "该工程尚未在 Unity 中打开，请先打开工程，待插件连接后再体检": "このプロジェクトはまだ Unity で開かれていません。プロジェクトを開き、プラグインの接続後にチェックしてください",
    "Unity 正在编译或导入，请待其完成后再体检": "Unity がコンパイルまたはインポート中です。完了してからチェックしてください",
    "Unity 处于 Play 模式，请先退出 Play 模式再体检": "Unity が Play モードです。Play モードを終了してからチェックしてください",
    "该工程的 Unity 插件为旧版，不支持体检：请在流水线页点击「更新」，待 Unity 编译完成后重试": "このプロジェクトの Unity プラグインは旧バージョンのため、チェックに対応していません。パイプラインタブで「更新」をクリックし、Unity のコンパイル完了後にお試しください",
    "无法解析 Unity 返回的体检结果": "Unity から返されたチェック結果を解析できません",
