    "请切换到 Unity 窗口等待编译完成（右下角加载图标消失），如有红色报错需先解决": "Unity のウィンドウに切り替えて、コンパイルの完了（右下の読み込みアイコンが消える）をお待ちください。赤いエラーがある場合は先に解決が必要です",
    "Unity 未响应，可能正在编译、导入，或有对话框等待操作": "Unity が応答しません。コンパイル中・インポート中か、ダイアログが操作待ちの可能性があります",
