    "该工程未安装 UnitySkills，请先点击「安装并打开 Unity」": "このプロジェクトには UnitySkills がインストールされていません。先に「インストールして Unity を開く」をクリックしてください",
    "UnitySkills 服务未启动，请在 Unity 中打开 Window > UnitySkills 并点击 Start Server": "UnitySkills が起動していません。Unity で Window > UnitySkills を開き、Start Server をクリックしてください",
    "无法连接 Unity 中的 UnitySkills（可能正在重新编译），请稍后重试": "Unity 内の UnitySkills に接続できません（再コンパイル中の可能性があります）。しばらくしてからお試しください",
