    "解压密码错误，请更换密码后重试（密码通常位于商品说明、卖家消息或压缩包旁的文本文件中）": "展開パスワードが違います。別のパスワードでお試しください（パスワードは通常、商品説明・出品者からのメッセージ・アーカイブと同じ場所のテキストファイルに記載されています）",
