    "场景已存在": "シーンがすでに存在します",
    "场景保存失败": "シーンを保存できませんでした",
    "Modular Avatar 无法将该素材的骨架对应到模型，可能不是为该素体制作，或骨架结构特殊，目前仅放置在模型下，不会跟随模型运动": "Modular Avatar でこのアセットのアーマチュアをアバターに対応付けられませんでした。この素体向けではないか、アーマチュア構造が特殊な可能性があります。現在はアバターの下に置いてあるだけで、アバターの動きには追従しません",
    "该素材不含骨架（配饰、道具等），已放置在模型下，需手动调整位置或挂到对应骨骼上": "このアセットにはアーマチュアがありません（アクセサリー・小物など）。アバターの下に配置したので、手動で位置を調整するか、対応するボーンに取り付けてください",
    "隐藏的物体同样计入：同款不同配色只需装配一件，其余配色在菜单中做成换色项；不再使用的素材可从模型上移除": "非表示のオブジェクトも数えられます。同じ衣装の色違いは 1 着だけセットアップし、ほかのカラーはメニューのカラー切り替え項目にしてください。使わなくなったアセットはアバターから外せます",
    "隐藏的物体同样计入：同款不同配色只需装配一件，其余配色在菜单中做成换色项": "非表示のオブジェクトも数えられます。同じ衣装の色違いは 1 着だけセットアップし、ほかのカラーはメニューのカラー切り替え項目にしてください",
    "不再使用的素材可从模型上移除": "使わなくなったアセットはアバターから外せます",
    "请先按素材说明安装所需的插件（常见的有 Modular Avatar、VRCFury 或素材自带的框架包）": "先にアセットの説明に従って必要なプラグイン（Modular Avatar・VRCFury・アセット付属のフレームワークなど）をインストールしてください",
    "插件的动画按物体路径查找，不能改名放置：请先在 Unity 中处理同名物体后重试": "プラグインのアニメーションはオブジェクトのパスで対象を探すため、名前を変えて配置することはできません。先に Unity で同名のオブジェクトを処理してからお試しください",
    "素材自带的动画若按原名查找物体，将不会生效": "アセット付属のアニメーションが元の名前でオブジェクトを探す場合は、機能しません",
    "当前版本的 Modular Avatar 不支持 Setup Outfit 接口（需要 1.8 以上）": "現在のバージョンの Modular Avatar は Setup Outfit に対応していません（1.8 以上が必要）",
