    "模型上有 VRCFury 组件，其参数无法预估，未计入），超出上限将导致上传失败，可减少部件开关的数量（如已安装 VRCFury，或可压缩至上限内）": "アバターに VRCFury コンポーネントがあり、そのパラメータは見積もれないため含めていません。上限を超えるとアップロードに失敗するため、パーツのトグルを減らしてください（VRCFury を導入済みなら、上限内に圧縮できる場合があります）",
    "有菜单项缺少名称（label）": "名前（label）のないメニュー項目があります",
    "不能将模型本身作为衣服开关": "アバター自体を衣装のトグルにはできません",
    "当前版本的 Modular Avatar 不含 Material Setter（需要 1.12 以上），无法生成共用模型的配色": "現在のバージョンの Modular Avatar には Material Setter がないため（1.12 以上が必要）、モデルを共用するカラー切り替えを生成できません",
