    "当前版本的 MA Material Setter 结构不兼容，Modular Avatar 版本可能过旧": "現在のバージョンの MA Material Setter は構造に互換性がありません。Modular Avatar のバージョンが古い可能性があります",
    "当前版本的 MA Object Toggle 结构不兼容，Modular Avatar 版本可能过旧（需要 1.12 以上）": "現在のバージョンの MA Object Toggle は構造に互換性がありません。Modular Avatar のバージョンが古い可能性があります（1.12 以上が必要）",
