    "该 prefab 的材质缺少着色器（显示为粉色），请先安装对应的着色器": "この prefab のマテリアルにシェーダーがありません（ピンク色で表示されます）。先に対応するシェーダーをインストールしてください",
    "渲染失败": "レンダリングに失敗しました",
    // --- the Unity plugin: the check-up ---
    "以上为构建前的数值：上传时 Modular Avatar、Avatar Optimizer（AAO）、VRCFury 会在构建阶段改动模型，实际数值会有出入（AAO 通常会减少网格、材质槽和骨骼的数量）": "以上はビルド前の数値です。アップロード時には Modular Avatar・Avatar Optimizer（AAO）・VRCFury がビルド中にアバターを変更するため、実際の数値とは差が出ます（AAO は通常、メッシュ・マテリアルスロット・ボーンの数を減らします）",
    "Unity 处于 Play 模式，请先退出 Play 模式再体检（Play 模式下模型已被插件处理，数值与编辑时不同）": "Unity が Play モードです。Play モードを終了してからチェックしてください（Play モードではアバターがプラグインで処理済みのため、編集時と数値が異なります）",
    "未找到": "見つかりません",
    "该工程未安装 VRChat SDK（Avatars），请先在 ALCOM 或 VCC 中安装": "このプロジェクトには VRChat SDK（Avatars）がインストールされていません。先に ALCOM または VCC でインストールしてください",
    "模型的根物体上需要有 VRC Avatar Descriptor 组件": "アバターのルートオブジェクトには VRC Avatar Descriptor コンポーネントが必要です",
