    "VRCFury 在构建时生成": "VRCFury がビルド時に生成",
    "无法预估": "見積もり不可",
    "同步参数超过 256 位，上传会被拒绝": "同期パラメータが 256 ビットを超えているため、アップロードが拒否されます",
    "请减少部件开关的数量（每个开关占 1 位，一组互斥的衣服占 8 位），或使用 VRCFury 的参数压缩功能": "パーツのトグルを減らすか（トグル 1 つにつき 1 ビット、排他の衣装グループは 8 ビット）、VRCFury のパラメータ圧縮機能を使用してください",
    "模型上有 VRCFury 组件，它的参数在构建时才生成，实际位数只会更多": "アバターに VRCFury コンポーネントがあります。そのパラメータはビルド時に生成されるため、実際のビット数はこれより多くなります",
    "当前已接近 256 位的上限，上传失败时请减少部件开关，或使用 VRCFury 的参数压缩功能": "すでに 256 ビットの上限に近づいています。アップロードに失敗する場合は、パーツのトグルを減らすか、VRCFury のパラメータ圧縮機能を使用してください",
    "PhysBone 组件": "PhysBone コンポーネント",
    "PhysBone 组件超过 256 个，上传会被拒绝": "PhysBone コンポーネントが 256 個を超えているため、アップロードが拒否されます",
    "隐藏的衣服同样计入：请移除不常用的衣服，或让同款不同配色的衣服共用一份物理（只装配一件，其余配色改为换色开关）": "非表示の衣装も数えられます。あまり使わない衣装を外すか、同じ衣装の色違いで物理を共用してください（1 着だけセットアップし、ほかのカラーはカラー切り替えのトグルにします）",
    "丢失的脚本": "Missing スクリプト",
    "这些物体上有脚本丢失的组件，说明该脚本所属的插件没有安装，带着它上传会失败或功能缺失": "これらのオブジェクトにはスクリプトが見つからないコンポーネントがあります。そのスクリプトを含むプラグインがインストールされていないことを意味し、このままアップロードすると失敗するか、機能が欠けます",
    "请在 ALCOM 或 VCC 中为工程安装对应的插件（常见的是 Modular Avatar、VRCFury）；确认不再需要时，可在 Unity 的 Inspector 中移除该组件": "ALCOM または VCC で、対応するプラグイン（多くは Modular Avatar・VRCFury）をプロジェクトにインストールしてください。不要と確認できた場合は、Unity の Inspector でそのコンポーネントを削除できます",
    "菜单单页的控件": "メニュー 1 ページのコントロール数",
    "菜单的一页最多放 8 个控件，超出时无法上传": "メニューの 1 ページに置けるコントロールは 8 個までで、超えるとアップロードできません",
    "请在 Unity 中打开对应的菜单资产，把多出的控件移入子菜单": "Unity で該当のメニューアセットを開き、超過分のコントロールをサブメニューに移してください",
    "主菜单": "メインメニュー",
    "材质槽为空": "マテリアルスロットが空",
    "着色器未安装": "シェーダー未インストール",
    "着色器不受支持": "シェーダー非対応",
    "粉色或缺失的材质": "ピンク色または欠落したマテリアル",
    "这些材质在游戏中会显示为粉色": "これらのマテリアルはゲーム内でピンク色に表示されます",
    "多数情况是着色器插件没有安装：请在 ALCOM 或 VCC 中为工程安装对应的着色器（如 lilToon、Poiyomi），待 Unity 编译完成后重新体检": "多くの場合、シェーダーのパッケージがインストールされていません。ALCOM または VCC で対応するシェーダー（lilToon・Poiyomi など）をプロジェクトにインストールし、Unity のコンパイル完了後にもう一度チェックしてください",
    "材质槽为空时，请在 Unity 中为该网格重新指定材质": "マテリアルスロットが空の場合は、Unity でそのメッシュにマテリアルを割り当て直してください",
    "没有网格的蒙皮网格": "メッシュのない Skinned Mesh",
    "这些 Skinned Mesh Renderer 没有指定网格，在游戏中不会显示": "これらの Skinned Mesh Renderer にはメッシュが指定されておらず、ゲーム内で表示されません",
    "通常是模型文件（FBX）没有导入或已被移动，请重新导入对应的素材": "多くの場合、モデルファイル（FBX）がインポートされていないか、移動されています。該当のアセットをインポートし直してください",
    "4096 像素以上的贴图": "4096 px 以上のテクスチャ",
    "占用显存最多的贴图": "VRAM 使用量の多いテクスチャ",
    "分辨率达到 4096 像素的贴图占用显存较多，容易使模型的贴图显存评级变差": "解像度 4096 px のテクスチャは VRAM を多く消費し、アバターのテクスチャメモリのランクが下がりやすくなります",
    "可在 Unity 中选中该贴图，将导入设置中的 Max Size 改为 2048": "Unity でそのテクスチャを選択し、インポート設定の Max Size を 2048 に変更できます",
