    "可移除不常用的衣服和配饰，或安装 Avatar Optimizer（AAO），在构建时自动移除被遮挡的网格": "あまり使わない衣装やアクセサリーを外すか、Avatar Optimizer（AAO）をインストールしてください。ビルド時に隠れたメッシュを自動で削除します",
