    "安装 Avatar Optimizer（AAO）并在模型上添加 Trace And Optimize 组件后，构建时会自动合并网格": "Avatar Optimizer（AAO）をインストールし、アバターに Trace And Optimize コンポーネントを追加すると、ビルド時にメッシュが自動で結合されます",
    "网格偏多": "Mesh が多めです",
    "材质槽偏多": "マテリアルスロットが多めです",
    "安装 Avatar Optimizer（AAO）并在模型上添加 Trace And Optimize 组件后，构建时会自动合并相同的材质槽": "Avatar Optimizer（AAO）をインストールし、アバターに Trace And Optimize コンポーネントを追加すると、ビルド時に同じマテリアルスロットが自動で結合されます",
    "骨骼偏多": "ボーンが多めです",
    "每件衣服都带着一套骨骼：可移除不常用的衣服，或安装 Avatar Optimizer（AAO），在构建时自动移除无用的骨骼": "衣装ごとにボーン一式が付いています。あまり使わない衣装を外すか、Avatar Optimizer（AAO）をインストールしてください。ビルド時に不要なボーンを自動で削除します",
    "PhysBone 组件偏多": "PhysBone コンポーネントが多めです",
    "隐藏的衣服同样计入：可移除不常用的衣服，或让同款不同配色的衣服共用一份物理": "非表示の衣装も数えられます。あまり使わない衣装を外すか、同じ衣装の色違いで物理を共用してください",
    "受 PhysBone 影响的骨骼偏多": "PhysBone の影響を受けるボーンが多めです",
    "头发、尾巴和飘带占得最多，可移除不常用的衣服，或让同款不同配色的衣服共用一份物理": "髪・しっぽ・リボンなどが特に多くを占めます。あまり使わない衣装を外すか、同じ衣装の色違いで物理を共用してください",
    "PhysBone 碰撞体偏多": "PhysBone コライダーが多めです",
    "可移除不常用的衣服，或在 PhysBone 组件中去掉不需要的碰撞体": "あまり使わない衣装を外すか、PhysBone コンポーネントから不要なコライダーを外してください",
    "PhysBone 碰撞检测次数偏多": "PhysBone の衝突判定数が多めです",
    "可在 PhysBone 组件中减少碰撞体，或移除不常用的衣服": "PhysBone コンポーネントのコライダーを減らすか、あまり使わない衣装を外してください",
    "实时灯光对性能影响很大，建议移除模型上的灯光": "リアルタイムライトはパフォーマンスへの影響が大きいため、アバター上のライトを外すことをおすすめします",
    "粒子系统偏多，建议移除不需要的特效": "パーティクルシステムが多めです。不要なエフェクトを外すことをおすすめします",
    "粒子数量偏多，建议降低粒子系统的 Max Particles": "パーティクル数が多めです。パーティクルシステムの Max Particles を下げることをおすすめします",
    "贴图显存偏高": "テクスチャメモリが多めです",
    "可在贴图的导入设置中将 Max Size 由 4096 改为 2048，并保持压缩开启": "テクスチャのインポート設定で Max Size を 4096 から 2048 に変更し、圧縮を有効のままにしてください",
    "模型的包围盒过大": "アバターのバウンディングボックスが大きすぎます",
    "请检查是否有物体离模型很远，或网格的 Bounds 被设置得过大": "アバターから大きく離れたオブジェクトがないか、メッシュの Bounds が大きすぎる設定になっていないかご確認ください",
    "该项超出 Poor 档的上限，模型的整体评级因此为 Very Poor，部分玩家的性能设置会默认不显示这类模型": "この項目が Poor の上限を超えているため、アバター全体のランクが Very Poor になります。パフォーマンス設定によっては、このようなアバターが既定で表示されないプレイヤーもいます",
