    "100 KB 以上": "100 KB 以上",
    "Avatar Explorer 的文件夹": "Avatar Explorer のフォルダー",
    "Booth 已购文件有更新": "Booth の購入済みファイルに更新があります",
    "Gumroad 已购文件有更新": "Gumroad の購入済みファイルに更新があります",
    "Booth、Gumroad、百度网盘的登录状态和 AI 服务的 API Key 已针对本机的 Windows 账户加密，无法迁移，不会导出；在另一台电脑上需重新登录并重新填写 API Key": "Booth・Gumroad・Baidu Netdisk のログイン状態と AI サービスの API キーは、この PC の Windows アカウント用に暗号化されているため移行できず、エクスポートされません。別の PC では再度ログインし、API キーを入力し直してください",
    "AI 服务的地址与模型、代理、下载位置和工程体检记录属于本机设置，同样不会导出，导入时也不会改动本机的这些设置": "AI サービスのアドレスとモデル、プロキシ、ダウンロード先、プロジェクトのチェック記録はこの PC の設定です。これらもエクスポートされず、インポートしてもこの PC の設定は変わりません",
    "ItemsData.json 的格式无法识别": "ItemsData.json の形式を認識できません",
    "items.json 的格式无法识别": "items.json の形式を認識できません",
