    "Unity 工程文件夹在本机的位置（选填）": "この PC での Unity プロジェクトフォルダーの場所（任意）",
    "上次导入前的素材库已备份，可恢复到导入前的状态": "前回のインポート前のライブラリはバックアップ済みで、インポート前の状態に戻せます",
