    "不在素材文件夹内的素材不会处理；如需收录，请先在「设置」中添加其所在的文件夹": "アセットフォルダー外のアセットは処理されません。取り込むには、先に「設定」でそのフォルダーを追加してください",
    "不在素材文件夹或下载文件夹内，未移动": "アセットフォルダーにもダウンロードフォルダーにもないため、移動していません",
