    "以下文件将移至回收站": "以下のファイルをごみ箱に移動します",
    "以下文件未移动：": "以下のファイルは移動していません：",
    "以导出文件中的内容替换当前素材库和数据文件": "現在のライブラリとデータファイルを、エクスポートファイルの内容で置き換えます",
    "份数": "個数",
    "位于 Unity 工程内，未移动": "Unity プロジェクト内にあるため、移動していません",
    "使用过 Avatar Explorer 的玩家，可将其中记录的素材信息（Booth 商品、分类、适配素体、标签、备注、封面）补充到本素材库。扫描时会自动跳过 Avatar Explorer 的数据库和备份，只收录其中的素材文件夹": "Avatar Explorer を使っていた場合、そこに記録されたアセット情報（Booth 商品、カテゴリ、対応素体、タグ、メモ、カバー）をこのライブラリに取り込めます。スキャン時は Avatar Explorer のデータベースとバックアップを自動的に除外し、アイテムフォルダーだけを取り込みます",
    "保留当前素材库，加入导出文件中的内容。同一素材的备注以当前素材库为准，为空时采用导出文件中的内容；标签合并": "現在のライブラリを残したまま、エクスポートファイルの内容を追加します。同じアセットのメモは現在のライブラリを優先し、空の場合のみエクスポートファイルの内容を使います。タグは統合されます",
    "全部文件": "すべてのファイル",
    "全部更新成功后，将旧版本移至回收站": "すべて更新できたら、旧バージョンをごみ箱に移動する",
    "关闭此窗口后更新仍在后台进行，可在素材详情中查看": "このウィンドウを閉じても更新はバックグラウンドで続きます。進行状況はアセットの詳細で確認できます",
    "其中包含素材文件夹、Unity 工程或刚下载的文件，未移动": "アセットフォルダー、Unity プロジェクト、またはダウンロード直後のファイルを含むため、移動していません",
