    "各素体在每个分类下的素材数量，来自素材的「适配素体」信息。点击数字可在素材库中查看对应的素材": "各素体のカテゴリ別アセット数です（アセットの「対応素体」情報に基づく）。数字をクリックすると、該当するアセットをライブラリで表示します",
    "合计": "合計",
