    "导出文件内的素材库数据已损坏，无法导入": "エクスポートファイル内のライブラリデータが破損しているため、インポートできません",
    "导出文件解压后的大小超出限制，已停止导入": "エクスポートファイルの展開後サイズが上限を超えたため、インポートを中止しました",
    "导出文件解压后的大小超出限制，已拒绝导入": "エクスポートファイルの展開後サイズが上限を超えるため、インポートを拒否しました",
