    "已默认勾选正在使用该素材的工程（已隐藏的工程除外）。将依次下载新版本、解压并导入所选工程：工程中已有的文件原位更新，已安装的插件（Packages）不会被覆盖。未勾选工程时仅下载新版本": "このアセットを使用中のプロジェクトが既定で選択されています（非表示のプロジェクトを除く）。新しいバージョンをダウンロードして展開し、選択したプロジェクトへ順にインポートします。プロジェクト内の既存ファイルはその場で更新され、インストール済みパッケージ（Packages）は上書きされません。プロジェクトを選択しない場合は、新しいバージョンのダウンロードのみ行います",
