    // --- 1.7.6: check-up fixes and report ---
    "贴图降到 2048": "テクスチャを 2048 に下げる",
    "移除灯光": "ライトを削除",
    "移除丢失的脚本": "Missing スクリプトを削除",
    "改动贴图的导入设置并重新导入，可恢复": "テクスチャのインポート設定を変更して再インポートします。元に戻せます",
    "仅在确认这些组件已不再需要时使用；若是插件未安装，请先安装插件": "これらのコンポーネントが不要だと確認できた場合にのみ使ってください。プラグインが未インストールの場合は、先にインストールしてください",
    "这些贴图不在 Assets 文件夹内，或没有可调整的导入设置": "これらのテクスチャは Assets フォルダーの外にあるか、変更できるインポート設定がありません",
    "部分已恢复": "一部を元に戻しました",
    "贴图的导入设置对整个工程生效，使用这些贴图的其他模型和场景也会随之改变": "テクスチャのインポート設定はプロジェクト全体に適用されます。同じテクスチャを使うほかのアバターやシーンも変わります",
    "如果脚本丢失是因为插件（Modular Avatar、VRCFury 等）没有安装或编译出错，请不要移除，应先安装或修复该插件：移除后，这些组件上的设置（衣服的装配、菜单项等）在场景保存后无法找回，重新安装插件也不会恢复": "スクリプトが Missing になっている原因がプラグイン（Modular Avatar、VRCFury など）の未インストールやコンパイルエラーである場合は、削除せず、先にそのプラグインをインストールまたは修復してください。削除すると、これらのコンポーネントの設定（衣装の着せ付け、メニュー項目など）はシーンの保存後には取り戻せず、プラグインを入れ直しても元に戻りません",
    "保存场景前可在 Unity 中按 Ctrl+Z 或点击「撤销上一步」撤销": "シーンを保存するまでは、Unity で Ctrl+Z を押すか、「直前の操作を取り消す」をクリックすると取り消せます",
    "确认这些组件已不再需要，是否继续？": "これらのコンポーネントは本当に不要ですか？続行しますか？",
