    "导入设置不在 Unity 的撤销记录中，处理后可在体检面板中点击「恢复」改回原设置": "インポート設定は Unity の取り消し履歴に入りません。処理後にアップロード前チェックのパネルで「元に戻す」をクリックすると元の設定に戻せます",
    "会移除模型下丢失脚本的组件": "アバター配下の Missing スクリプトのコンポーネントを削除します",
    "保存场景前可用 Ctrl+Z 撤销": "シーンを保存するまでは Ctrl+Z で取り消せます",
    "此前已改动的贴图可在体检面板中点击「恢复」改回原设置": "それまでに変更したテクスチャは、アップロード前チェックのパネルで「元に戻す」をクリックすると元の設定に戻せます",
    "工程中有脚本编译错误，未执行移除：此时显示为丢失的脚本可能只是暂时无法加载（例如 Modular Avatar、VRCFury 在 SDK 更新后编译失败），移除后其设置无法找回": "プロジェクトにスクリプトのコンパイルエラーがあるため、削除は行いませんでした。いま Missing と表示されているスクリプトは、一時的に読み込めないだけの可能性があります（SDK の更新後に Modular Avatar や VRCFury がコンパイルに失敗している場合など）。削除するとその設定は取り戻せません",
