    "在 platform.deepseek.com 申请 API Key。模型：deepseek-flash（推荐：DeepSeek 最新的 Flash 模型，能力和价格都优于 deepseek-v4-pro，支持识图）、deepseek-v4-pro（上一代，价格约为 deepseek-flash 的 3～4 倍，不支持识图，截图时自动由 deepseek-flash 代为描述）。旧名称 deepseek-chat / deepseek-reasoner / deepseek-v4-flash 已停用": "platform.deepseek.com で API Key を取得します。モデル：deepseek-flash（推奨：DeepSeek の最新の Flash モデル。性能・価格とも deepseek-v4-pro より優れ、画像認識に対応）、deepseek-v4-pro（旧世代。価格は deepseek-flash の約 3～4 倍、画像認識非対応。スクリーンショットは deepseek-flash が自動で説明します）。旧名称の deepseek-chat / deepseek-reasoner / deepseek-v4-flash は廃止されました",
    "DeepSeek 在北京时间工作日 9:00–12:00、14:00–18:00 为高峰时段，价格为其余时段的 2 倍；法定节假日全天按低峰计（按国务院公布的放假安排，尚未公布的年份按工作日估算）": "DeepSeek は平日 9:00–12:00・14:00–18:00（北京時間）がピーク時間帯で、それ以外の 2 倍の価格です。中国の祝日は終日オフピークとして計算します（国務院が公表した休日の日程によります。未公表の年は平日として概算します）",
