    "分享到社区": "コミュニティで共有",
    "提交到 MioVRCA 社区方案库（GitHub），审核通过后，所有玩家都能在「社区方案」中找到它": "MioVRCA のコミュニティのプリセット集（GitHub）に投稿します。審査を通ると、すべてのプレイヤーが「コミュニティのプリセット」で見つけられるようになります",
    "需要登录 GitHub；提交前可以在网页上补充说明": "GitHub へのログインが必要です。投稿前にページ上で説明を追加できます",
    "在 GitHub 上提交…": "GitHub で投稿…",
    "分享的内容只有素材在工程中的位置、商品页和菜单结构，不包含素材文件和本机路径；朋友需要自己拥有这些素材": "共有されるのは、プロジェクト内のアセットの位置・商品ページ・メニュー構成だけで、アセットのファイルやこのパソコンのパスは含まれません。友だちはアセットを自分で持っている必要があります",
    "粘贴朋友发来的分享码（以 MIOVRCA-RECIPE-1: 开头）": "友だちから届いた共有コード（MIOVRCA-RECIPE-1: で始まる）を貼り付けてください",
    "连同前后的聊天文字一起粘贴也可以": "前後のチャットの文章ごと貼り付けてもかまいません",
    "正在读取社区方案…": "コミュニティのプリセットを読み込んでいます…",
