    "社区实测数据": "コミュニティの実測データ",
    "查看和分享…": "表示と共有…",
    "流水线验收时记下每件衣服在素体上是否穿模、怎样修好的，下次装配同一件衣服时自动套用；分享给社区后，其他玩家装配时也能用上": "パイプラインの確認時に、各衣装が素体で貫通するか、どう直したかを記録し、次に同じ衣装をセットアップするときに自動で使います。コミュニティで共有すると、ほかのプレイヤーも使えるようになります",
