    "流水线验收时，会记下每件衣服在素体上是否穿模、怎样修好的（例如穿着时设置哪些收缩形态键）": "パイプラインの確認時に、各衣装が素体で貫通するか、どう直したか（着用時にどの縮小シェイプキーを設定したかなど）を記録します",
    "下次在同一个素体上装配同一件衣服，会先套用这些设置再验收": "次に同じ素体へ同じ衣装をセットアップするときは、この設定を先に適用してから確認します",
