    "分享码较长，已复制：请在打开的页面中粘贴到「实测数据分享码」一栏": "共有コードが長いためコピーしました。開いたページの「実測データの共有コード」欄に貼り付けてください",
    "清空本机的全部实测记录？已分享给社区的不受影响": "このパソコンの実測記録をすべて消去しますか？コミュニティで共有したものには影響しません",
