    "玩家用 MioVRCA 装配时，会按它选用对应素体的版本、设置穿着时的形态键、生成部件开关": "プレイヤーが MioVRCA でセットアップするとき、それに従って素体に合ったバージョンを選び、着用時のシェイプキーを設定し、パーツのスイッチを作ります",
